<?php
/** Proof — who sees which view (spec "Proof", 2): Priya the standard ones and none of Marco's; Marco IT's queue views, not Facilities'; a standard view's delete → 422; Priya's global view_create → 403 in words; a lead changes a shared one, support cannot. */
require __DIR__ . '/lib.php';
$W = world();
$priya = as_member(26); $marco = as_member(27); $lena = as_member(28); $colin = as_member(29);
echo "1. Marco's personal view, Lena's queue views\n";
[$c, $b] = act($marco, '/views/save.php', ['name' => 'SMOKE Marco private', 'scope' => 'personal', 'filters' => json_encode(['assignee' => 'me'])]);
$mv = (int) $b['record_id'];
ok($c === 200 && $mv > 0 && (int) view_row($mv)['owner_member_id'] === 27, 'Marco saves a personal view (support has views.personal)');
[$c, $b] = act($lena, '/views/save.php', ['name' => 'SMOKE IT board', 'scope' => 'queue', 'queue' => $W['it'], 'layout' => 'board', 'filters' => json_encode(['queue_id' => [$W['it']]]), 'board' => json_encode(['column_field' => 'status', 'wip' => ['open' => 2], 'solved_days' => 7])]);
$itv = (int) $b['record_id'];
ok($c === 200 && $itv > 0 && view_row($itv)['scope'] === 'queue' && (int) view_row($itv)['queue_id'] === $W['it'] && view_row($itv)['layout'] === 'board', 'Lena saves a queue board for IT help');
[$c, $b] = act($lena, '/views/save.php', ['name' => 'SMOKE Facilities list', 'scope' => 'queue', 'queue' => $W['fac'], 'filters' => json_encode(['queue_id' => [$W['fac']]])]);
ok($c === 422 && isset(fields($b)['queue']), 'a queue view for Facilities, which Lena does not hold (view_all is not holding): 422');
act(as_member(1), '/settings/queues/member.php', ['queue' => $W['fac'], 'member' => 28]);
[$c, $b] = act($lena, '/views/save.php', ['name' => 'SMOKE Facilities list', 'scope' => 'queue', 'queue' => $W['fac'], 'filters' => json_encode(['queue_id' => [$W['fac']]])]);
$facv = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $facv > 0, 'once she is a member of Facilities: saved');
[$c, $b] = act($lena, '/views/save.php', ['name' => 'SMOKE Everyone', 'scope' => 'global', 'filters' => json_encode(['priority' => ['urgent']])]);
$gv = (int) $b['record_id'];
ok($c === 200 && $gv > 0, 'and a global view');
echo "2. Who sees what\n";
$names = fn (string $jar) => array_map(fn ($v) => $v['name'], screen($jar, '/views/')[1]['views'] ?? []);
$p = $names($priya);
ok(count(array_filter($p, fn ($n) => in_array($n, ['My tickets', 'Needs my reply', 'Unassigned', 'Triage', 'At risk', 'Stale', 'My requests', 'Team board'], true))) === 8 && !in_array('SMOKE Marco private', $p, true) && !in_array('SMOKE IT board', $p, true) && in_array('SMOKE Everyone', $p, true), 'Priya: the eight standard views and the global one, none of Marco\'s or the queues\'');
$r = page($priya, '/views/' . $mv . '/edit');
ok($r['code'] === 403, 'Priya opening the view form: 403 (no views right)');
[$c, $b] = act($priya, '/views/save.php', ['name' => 'SMOKE Priya global', 'scope' => 'global']);
ok($c === 403 && msg($b) === 'You may not change shared views.', 'Priya\'s view_create with scope global: 403 "You may not change shared views."');
[$c, $b] = act($priya, '/views/save.php', ['name' => 'SMOKE Priya personal', 'scope' => 'personal']);
ok($c === 403, 'and a personal one: 403 (a requester has no views.personal)');
$m = $names($marco);
ok(in_array('SMOKE Marco private', $m, true) && in_array('SMOKE IT board', $m, true) && !in_array('SMOKE Facilities list', $m, true) && in_array('SMOKE Everyone', $m, true), 'Marco: his own, IT\'s queue view, the global one, not Facilities\'');
ok(page($marco, '/views/' . $facv . '/edit')['code'] === 404 && str_contains(page($marco, '/views/' . $facv . '/edit')['body'], 'View not found.'), 'a direct URL to Facilities\' view: 404 "View not found."');
ok(page($lena, '/views/' . $mv . '/edit')['code'] === 404, 'Lena cannot open Marco\'s personal view either (not hers)');
ok(page($priya, '/inbox?view=' . $mv)['code'] === 403 && inbox_ids($colin, 'view=' . $mv) === inbox_ids($colin, ''), 'the inbox ignores a view one may not see');
ok(page($marco, '/board?view=' . $facv)['code'] === 404, 'the board with Facilities\' view: 404 for Marco');
echo "3. Changing and deleting\n";
$sys = (int) one("SELECT id FROM saved_views WHERE system_key = 'triage'");
[$c, $b] = act($lena, '/views/delete.php', ['view' => $sys]);
ok($c === 422 && msg($b) === 'A standard view cannot be changed — save a copy.', 'deleting a standard view: 422 in the sentence');
[$c, $b] = act($lena, '/views/save.php', ['view' => $sys, 'name' => 'Renamed']);
ok($c === 422 && str_contains(msg($b), 'save a copy'), 'changing one: 422');
[$c, $b] = act($lena, '/views/save.php', ['view' => $sys, 'copy' => 'yes', 'name' => 'SMOKE Triage copy', 'scope' => 'personal']);
$copy = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $copy > 0 && $copy !== $sys && json_decode(view_row($copy)['filters'], true) === ['status_category' => ['new']] && (bool) view_row($copy)['is_system'] === false, 'Save a copy: a personal view with the standard\'s filters');
$body = page($lena, '/views/' . $sys . '/edit')['body'];
ok(str_contains($body, 'id="view-form-standard-note"') && str_contains($body, 'Save a copy') && str_contains($body, 'name="copy"'), 'a standard view\'s form says so and offers Save a copy');
[$c, $b] = act($marco, '/views/save.php', ['view' => $itv, 'name' => 'SMOKE IT board (renamed by Marco)']);
ok($c === 403 && msg($b) === 'You may not change shared views.', 'support changing a queue view: 403');
[$c, $b] = act($marco, '/views/delete.php', ['view' => $gv]);
ok($c === 403, 'support deleting the global one: 403');
$since = last_activity_id();
[$c, $b] = act($lena, '/views/save.php', ['view' => $itv, 'name' => 'SMOKE IT board (renamed)', 'board' => json_encode(['column_field' => 'status', 'swimlane' => 'priority', 'wip' => ['open' => 3], 'solved_days' => 7])]);
$row = view_row($itv);
ok($c === 200 && $row['name'] === 'SMOKE IT board (renamed)' && json_decode($row['board'], true)['swimlane'] === 'priority' && json_decode($row['board'], true)['wip'] === ['open' => 3] && json_decode($row['filters'], true) === ['queue_id' => [$W['it']]], 'the lead renames it and sets a swimlane; the filters it was not sent are kept');
$l = activity('view.update', $since);
ok(count($l) === 1 && isset(json_decode($l[0]['after'], true)['name']) && isset(json_decode($l[0]['before'], true)['name']), 'view.update logged with the changed name');
[$c, $b] = act($lena, '/views/save.php', ['name' => 'SMOKE wrong queue', 'scope' => 'queue', 'queue' => 999999]);
ok($c === 422 && isset(fields($b)['queue']), 'a queue view needs a queue held: 422');
[$c, $b] = act($marco, '/views/delete.php', ['view' => $mv]);
ok($c === 200 && view_row($mv) === null && ($b['location'] ?? '') === '/views/?notice=deleted' && count(activity('view.delete', $since)) === 1, 'Marco deletes his own: gone, logged, lands on the list');
[$c, $d] = screen($lena, '/views/');
$v = array_values(array_filter($d['views'], fn ($x) => $x['view_id'] === $itv))[0];
ok($v['may_change'] === true && $v['count'] >= 2 && $v['layout'] === 'board', 'the list carries may_change, the count and the layout');
echo "4. The views list page\n";
$body = page($lena, '/views/')['body'];
ok(str_contains($body, 'id="views-group-standard"') && str_contains($body, 'id="view-card-' . $itv . '-edit"') && str_contains($body, 'id="view-card-' . $sys . '-open"') && !str_contains($body, 'id="view-card-' . $sys . '-edit"'), 'cards: Open on every view, Edit only on one I may change');
$body = page($colin, '/views/')['body'];
ok(str_contains($body, 'id="views-mine-empty"') && str_contains($body, 'Save any filtered list as a view'), 'empty Mine: the sentence');
finish();
